  async function renderBinderImage() {
    const s = load(), VC = visibleCards(s), cols = 8, cw = 132, ch = Math.round(cw * 1336 / 961), gap = 16, pad = 60, rows = Math.ceil(VC.length / cols);
    const W = pad * 2 + cols * cw + (cols - 1) * gap, top = 190, H = top + rows * ch + (rows - 1) * gap + 90;
    const cv = document.createElement('canvas'); cv.width = W; cv.height = H; const ctx = cv.getContext('2d');
    shareBg(ctx, W, H);
    const owned = VC.filter((c) => s.cards[c.id] && s.cards[c.id].n), exAll = VC.filter((c) => c.rarity === 'ex'), exOwned = exAll.filter((c) => s.cards[c.id] && s.cards[c.id].n);
    const holos = owned.filter((c) => s.cards[c.id].holo).length;
    ctx.textAlign = 'left'; ctx.fillStyle = '#fff'; ctx.font = '900 44px system-ui,Segoe UI,Arial'; ctx.fillText(`Le classeur de ${displayPseudo()}`, pad, 80);
    ctx.fillStyle = '#b9b3d1'; ctx.font = '600 22px system-ui,Segoe UI,Arial';
    ctx.fillText(`${owned.length}/${VC.length} cartes · ${exOwned.length}/${exAll.length} ex · ${holos} brillante${holos > 1 ? 's' : ''} · NNN 2026, cartes de Balade92`, pad, 118);
    rr(ctx, pad, 142, W - pad * 2, 14, 7); ctx.fillStyle = 'rgba(255,255,255,.08)'; ctx.fill();
    const pw = (W - pad * 2) * owned.length / VC.length;
    if (pw > 0) { const lg = ctx.createLinearGradient(pad, 0, pad + pw, 0); lg.addColorStop(0, '#7b3fe0'); lg.addColorStop(1, '#e04aa0'); rr(ctx, pad, 142, Math.max(14, pw), 14, 7); ctx.fillStyle = lg; ctx.fill(); }
    const list = VC.slice().sort((a, b) => a.num - b.num);
    const ims = await Promise.all(list.map((c) => (s.cards[c.id] && s.cards[c.id].n ? loadImg(c.img) : null)));
    list.forEach((c, i) => {
      const x = pad + (i % cols) * (cw + gap), y = top + Math.floor(i / cols) * (ch + gap), own = s.cards[c.id] && s.cards[c.id].n, k = fxOf(c);
      drawCard(ctx, ims[i], x, y, cw, ch, own ? { glow: k ? FX[k].color : null, holo: s.cards[c.id].holo } : { missing: true, num: c.num });
    });
    ctx.fillStyle = '#8f89aa'; ctx.font = '700 18px system-ui,Segoe UI,Arial'; ctx.textAlign = 'center';
    ctx.fillText('Topic No Nut November 2026 · jeuxvideo.com', W / 2, H - 34);
    return cv;
  }
  // Envoi direct sur NoelShack : renvoie le lien direct (image.noelshack.com/fichiers/…)
  function nsDirect(u) {
    u = String(u || '').trim().replace(/^http:/, 'https:');
    if (/image\.noelshack\.com\/fichiers\//.test(u)) return u;
    const m = u.match(/noelshack\.com\/(\d{4})-(\d{1,2})-(\d+)-(.+)$/);   // https://www.noelshack.com/2026-45-4-1762…-nom.png
    return m ? `https://image.noelshack.com/fichiers/${m[1]}/${m[2]}/${m[3]}/${m[4]}` : u;
  }
  function nsFind(txt) {
    let j = null; try { j = JSON.parse(txt); } catch (e) { j = null; }
    const cands = [];
    const walk = (v) => { if (typeof v === 'string') cands.push(v); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
    if (j) walk(j);
    (String(txt).match(/https?:\\?\/\\?\/[^"'\s<>]*noelshack\.com[^"'\s<>]*/g) || []).forEach((u) => cands.push(u.replace(/\\\//g, '/')));
    const u = cands.map((x) => x.replace(/\\\//g, '/')).find((x) => /noelshack\.com\/(fichiers\/|\d{4}-)/.test(x));
    return u ? nsDirect(u) : '';
  }
  function nsPost(url, field, blob, name) {
    return new Promise((resolve, reject) => {
      const fd = new FormData(); fd.append(field, blob, name);
      GM_xmlhttpRequest({
        method: 'POST', url, data: fd, timeout: 30000,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json, text/javascript, */*; q=0.01', Referer: 'https://www.noelshack.com/', Origin: 'https://www.noelshack.com' },
        onload: (r) => { const u = nsFind(r.responseText || ''); if (u) resolve(u); else reject(new Error('réponse inattendue (' + r.status + ')')); },
        onerror: () => reject(new Error('réseau')), ontimeout: () => reject(new Error('délai dépassé')),
      });
    });
  }
  async function noelshackUpload(blob, name) {
    try { return await nsPost('https://www.noelshack.com/envoi.json', 'fichier[]', blob, name); }
    catch (e) { return nsPost('https://www.noelshack.com/api.php', 'fichier', blob, name); }
  }
  async function openShare(kind, data) {
    if (!win) return;
    sfx.tick();
    const box = h(`<div class="bb-zoom bb-share"><div class="bb-share-in"><div class="bb-muted">Création de l'image…</div></div><button class="bb-x">✕</button></div>`);
    $('.bb-win', win).appendChild(box);
    $('.bb-x', box).onclick = () => box.remove();
    box.addEventListener('mousedown', (e) => { if (e.target === box) box.remove(); });
    let cv;
    try { cv = kind === 'binder' ? await renderBinderImage() : await renderOpeningImage(data); } catch (e) { $('.bb-share-in', box).innerHTML = '<p class="bb-muted">Impossible de créer l\'image.</p>'; return; }
    const url = cv.toDataURL('image/png');
    const name = kind === 'binder' ? 'classeur-nnn-2026.png' : 'booster-nnn-2026.png';
    $('.bb-share-in', box).innerHTML = `<img class="bb-share-img" src="${url}" alt="Aperçu de l'image à partager">
      <p class="bb-muted bb-ns-msg">Clique sur « Envoyer sur NoelShack » : l'image est mise en ligne et tu reçois directement le lien à coller sur le topic.</p>
      <div class="bb-ns-link" style="display:none;margin:8px 0"><input class="bb-ns-url" readonly style="width:min(520px,80vw);padding:7px 10px;border-radius:8px;border:1px solid #555;background:#111;color:#fff;font:600 13px monospace"> <button class="bb-btn gold bb-ns-cp">Copier le lien</button></div>
      <div class="row"><button class="bb-btn gold bb-ns">⬆ Envoyer sur NoelShack</button><button class="bb-btn bb-cp">Copier l'image</button><a class="bb-btn ghost" download="${name}" href="${url}">Télécharger</a></div>`;
    $('.bb-ns', box).onclick = async (e) => {
      const b = e.currentTarget, msg = $('.bb-ns-msg', box);
      b.disabled = true; b.textContent = 'Envoi en cours…';
      try {
        const blob = await new Promise((r) => cv.toBlob(r, 'image/png'));
        const link = await noelshackUpload(blob, name);
        $('.bb-ns-link', box).style.display = ''; $('.bb-ns-url', box).value = link;
        msg.textContent = 'Image en ligne ! Copie le lien et colle-le dans ton message.';
        b.textContent = '✔ Envoyée';
        try { await navigator.clipboard.writeText(link); msg.textContent = 'Image en ligne ! Le lien est déjà copié : colle-le dans ton message (Ctrl+V).'; } catch (err) { /* copie manuelle */ }
      } catch (err) {
        b.disabled = false; b.textContent = '⬆ Réessayer';
        msg.textContent = 'Envoi impossible (' + err.message + '). Tu peux toujours télécharger l\'image et l\'envoyer sur noelshack.com.';
      }
    };
    $('.bb-ns-cp', box).onclick = async () => { const i = $('.bb-ns-url', box); i.select(); try { await navigator.clipboard.writeText(i.value); toast('Lien copié !'); } catch (e) { document.execCommand('copy'); toast('Lien copié !'); } };
    $('.bb-cp', box).onclick = async (e) => {
      const b = e.currentTarget;
      try {
        const blob = await new Promise((r) => cv.toBlob(r, 'image/png'));
        await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
        b.textContent = 'Image copiée'; toast('Image copiée. Colle-la sur NoelShack avec Ctrl+V.');
      } catch (err) { b.textContent = 'Copie impossible : télécharge-la'; }
    };
  }

