        if (tp(F, 'gainRound')) { const v = tp(F, 'gainRound'); F.hp += v; F.max += v; st.ev.push({ k: 'heal', side: s, i: P.active, v }); L(st, `${cname(F.id)} récupère (+${v} PV).`, 'fx'); }
