      const shown = P.active === -1 ? lastActive[side] : P.active;
      const bench = P.team.map((F, i) => i === shown ? '' : `<div class="du-mini${F.ko || F.gone ? ' ko' : ''}" data-side="${side}" data-i="${i}" data-info="${F.id}" title="${esc(cname(F.id))}"><img src="${esc(byId[F.id].img)}" alt=""><span>${F.ko || F.gone ? 'KO' : F.hp + ' PV'}</span></div>`).join('');
