      $('.du-title', box).innerHTML = `${avHtml(ctl.avMe, ctl.mode === 'online' ? st.P[me].name : '')}${esc(st.P[me].name)} contre ${avHtml(ctl.avOp, ctl.mode === 'online' ? st.P[op].name : '')}${esc(st.P[op].name)}`;
