      const lastL = st.log[st.log.length - 1]; $('.du-last', box).textContent = lastL ? lastL.t : '';
      lg.scrollTop = lg.scrollHeight;
      const spec = ctl.mode === 'spectate', mine = spec ? [] : legal(st, me), myTurn = !spec && toMove(st).includes(me);
      const tt = $('.du-turn', box);
