      const want = d.mode === 'maxi' ? 'maxi' : 'classic';
      if (loadTeam().mode !== want) {   // on prend automatiquement un de ses decks du bon mode s'il est prêt
        const X = loadDecks(), cur = X.cur;
        const k = X.list.findIndex((dk, j) => { if ((dk.mode === 'maxi' ? 'maxi' : 'classic') !== want) return false; X.cur = j; saveDecks(X); return teamOk(loadTeam()); });
        if (k < 0) { X.cur = cur; saveDecks(X); loadTeam(); }
        else { X.cur = k; saveDecks(X); toast(`Deck « ${X.list[k].name} » sélectionné pour ce ${want === 'maxi' ? 'Maxi Duel' : 'duel classique'}.`); }
      }
      if (!teamOk(loadTeam())) { openWin('duel'); toast('Ton équipe n\'est pas prête : choisis-la dans l\'onglet Duels.'); db('PATCH', `duels/${v.duel}`, { status: 'refused' }).catch(() => {}); return; }
      if ((d.mode || 'classic') !== loadTeam().mode) { toast(d.mode === 'maxi' ? 'Ce défi est un Maxi Duel : choisis un deck en mode Maxi Duel puis demande-lui de te redéfier.' : 'Ce défi est un duel classique : choisis un deck en mode classique.'); db('PATCH', `duels/${v.duel}`, { status: 'refused' }).catch(() => {}); return; }
      try { await db('PATCH', `duels/${v.duel}`, { status: 'play', ab: myAvatar() }); } catch (e) { toast('Impossible de rejoindre : ' + e.message); return; }
