  /* ======================================================================
   *  DÉMARRAGE
   * ==================================================================== */
  // Démarrage protégé : une étape qui plante (page modifiée par un autre script, sauvegarde bizarre…) n'empêche jamais le bouton d'apparaître
  const safe = (fn, name) => { try { fn(); } catch (e) { console.warn('[Cartes NNN] ' + name, e); } };
  safe(refreshFab, 'bouton'); safe(scan, 'scan'); safe(recoverCards, 'récupération');
  // Cohabitation avec d'autres scripts (Super Smash Kheys…) : si le bouton disparaît ou se retrouve caché sous un autre bouton, on le remet
  let fabMoved = false;
  setInterval(() => safe(() => {
    let f = $('.bb-fab');
    if (!f || !f.isConnected) { refreshFab(); f = $('.bb-fab'); }
    else if (f.parentNode !== document.documentElement && f.parentNode !== document.body) document.body.appendChild(f);
    if (!f || win || fabMoved || GM_getValue('bb_fab_pos', null)) return;
    const r = f.getBoundingClientRect(), top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    let cov = null;
    if (top && !f.contains(top) && !(top.closest && top.closest('.bb-toast, .bb-invite, .bb-ov'))) for (let e = top; e && e !== document.body && e !== document.documentElement; e = e.parentElement) if (getComputedStyle(e).position === 'fixed') { cov = e; break; }
    if (cov) {   // un autre bouton flottant (Super Smash Kheys…) est par-dessus : on remonte le nôtre au-dessus de lui
      const o = cov.getBoundingClientRect(); fabMoved = true;
      f.style.bottom = 'auto'; f.style.top = Math.max(8, o.top - r.height - 16) + 'px';
    }
  }, 'surveillance du bouton'), 2000);
  let scanT;
  new MutationObserver((muts) => {
    if (muts.some((m) => [...m.addedNodes].some((n) => n.nodeType === 1 && !n.closest('.bb-ov, .bb-fab, .bb-toast')))) {
      clearTimeout(scanT); scanT = setTimeout(scan, 400);
    }
  }).observe(document.body, { childList: true, subtree: true });
  window.addEventListener('focus', refreshFab);   // synchro entre onglets

  if (NET.enabled()) NET.start();   // visible dans le salon des duels et prêt à recevoir des défis
  GM_registerMenuCommand('Ouvrir mes boosters', () => openWin('shop'));
  GM_registerMenuCommand('Ouvrir mon classeur', () => openWin('binder'));
  // rappel une fois par jour : le booster quotidien t'attend
  setTimeout(() => { const s = load(); if (dailyReady(s) && GM_getValue('bb_daily_toast', '') !== todayKey()) { GM_setValue('bb_daily_toast', todayKey()); toast(`🎁 Ton booster quotidien (${KINDS.daily.n} cartes) t'attend !`, true); } }, 1500);

